{"success": true, "data": {"stdout": "{"doc_id": "Essingen Islands", "input_text": "The Essingen Islands are a group of two islands — Stora Essingen and Lilla Essingen — in the Swedish lake of Mälaren , located southwest of Kungsholmen in Stockholm . On older maps , the islands are called Stora Hessingen and Lilla Hessingen . The islands were a part of the administrative Bromma Parish until 1916 , when they were incorporated with the parish into Stockholm Municipality . They remained a part of Bromma ecclesiastical parish until 1955 , when they received their own parish within the Church of Sweden . A bridge was built between the islands and Kungsholmen in 1907 , and between the islands themselves in 1917 . In 1966 , the Essingeleden motorway opened across the islands . The Alviksbron bridge ( for pedestrians , bicycles , and trams ) opened in 2000 .", "gold_entities": [{"text": "Essingen Islands", "type": "LOC"}, {"text": "two", "type": "NUM"}, {"text": "Stora Essingen", "type": "LOC"}, {"text": "Lilla Essingen", "type": "LOC"}, {"text": "Swedish", "type": "LOC"}, {"text": "Mälaren", "type": "LOC"}, {"text": "Kungsholmen", "type": "LOC"}, {"text": "Stockholm", "type": "LOC"}, {"text": "Bromma Parish", "type": "LOC"}, {"text": "1916", "type": "TIME"}, {"text": "Stockholm Municipality", "type": "LOC"}, {"text": "Bromma", "type": "LOC"}, {"text": "1955", "type": "TIME"}, {"text": "Church of Sweden", "type": "LOC"}, {"text": "1907", "type": "TIME"}, {"text": "1917", "type": "TIME"}, {"text": "1966", "type": "TIME"}, {"text": "Essingeleden motorway", "type": "LOC"}, {"text": "Alviksbron bridge", "type": "LOC"}, {"text": "2000", "type": "TIME"}], "gold_relations": [{"head": "Kungsholmen", "tail": "Stockholm", "type": "P131", "head_type": "LOC", "tail_type": "LOC"}, {"head": "Kungsholmen", "tail": "Stockholm Municipality", "type": "P131", "head_type": "LOC", "tail_type": "LOC"}, {"head": "Kungsholmen", "tail": "Swedish", "type": "P17", "head_type": "LOC", "tail_type": "LO